/** Projection constants captured at generation time. */
const PROJECTION = { minX: 1.189704365300343, maxY: 0.6634352420123096, scale: 1963.6295150212036 } as const;

/**
 * Longitude/latitude to a point in the map's coordinate space.
 *
 * Uses the identical Web Mercator maths the boundaries were generated with, so a
 * marker placed from real coordinates lands exactly where that place sits on the
 * drawn map — no hand-tuned offsets that silently rot when the geometry changes.
 */
export function projectToMap(lon: number, lat: number): { x: number; y: number } {
  const clamped = Math.max(Math.min(lat, 84), -84);
  const x = (lon * Math.PI) / 180;
  const y = Math.log(Math.tan(Math.PI / 4 + (clamped * Math.PI) / 360));

  return {
    x: (x - PROJECTION.minX) * PROJECTION.scale,
    y: (PROJECTION.maxY - y) * PROJECTION.scale,
  };
}
